const themeButton=document.querySelector('.theme-toggle');function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';themeButton.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);themeButton.textContent=dark?'☀':'◐';}updateThemeButton();themeButton.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('theme',document.documentElement.dataset.theme)}catch(e){}updateThemeButton()});
const filters=document.querySelectorAll('[data-filter]');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#project-count').textContent=button.dataset.filter==='all'?`Showing all ${count} projects`:`Showing ${count} ${button.dataset.filter.toLowerCase()} projects`;}));
const dialog=document.querySelector('.lightbox');let returnFocus;document.querySelectorAll('.zoom-image').forEach(link=>link.addEventListener('click',e=>{if(!dialog.showModal)return;e.preventDefault();returnFocus=link;dialog.querySelector('img').src=link.href;dialog.querySelector('img').alt=link.querySelector('img').alt;dialog.querySelector('p').textContent=link.querySelector('img').alt;dialog.showModal();document.body.style.overflow='hidden';}));dialog.querySelector('.close-viewer').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.style.overflow='';returnFocus?.focus()});
if(typeof window!=='undefined'){
 const hero=document.querySelector('[data-home-video]'),heroButton=document.querySelector('.hero-playback');if(hero&&heroButton){const sync=()=>heroButton.textContent=hero.paused?'Play video':'Pause video';heroButton.addEventListener('click',()=>{if(hero.paused)hero.play().catch(sync);else hero.pause()});hero.addEventListener('play',sync);hero.addEventListener('pause',sync);const motion=matchMedia('(prefers-reduced-motion: reduce)');if(!motion.matches){hero.autoplay=true;hero.play().catch(sync)}motion.addEventListener('change',e=>{if(e.matches)hero.pause()});}
 document.querySelectorAll('video[controls]').forEach(v=>v.addEventListener('play',()=>{document.querySelectorAll('video[controls]').forEach(other=>{if(other!==v)other.pause()})}));
 document.querySelectorAll('[data-gallery]').forEach(g=>{const track=g.querySelector('.gallery-track'),slides=[...track.querySelectorAll('figure')],prev=g.querySelector('[data-prev]'),next=g.querySelector('[data-next]'),count=g.querySelector('[data-count]');if(!prev||!next)return;const position=()=>Math.round(track.scrollLeft/Math.max(1,track.clientWidth));const update=()=>{const index=position();count.textContent=`${index+1}/${slides.length}`;prev.disabled=index===0;next.disabled=index===slides.length-1};const move=d=>track.scrollTo({left:Math.max(0,Math.min(slides.length-1,position()+d))*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',update);update();});
}
